// Regenerates docs/tools.md from docs/tools.json (itself generated by
// package/scripts/dump-tool-catalog.sh from the real LxTool instances) — so the tool
// reference can never drift from the actual schemas.
//
// The whole file is generated: the per-category framing prose lives in CATEGORIES below
// rather than in the output, so there is no hand-written region to preserve and no
// marker splicing. Every tool in tools.json must appear in exactly one category — a new
// tool that isn't mapped (or a typo'd name) fails this script loudly instead of silently
// vanishing from the docs.
//
//   node scripts/generate-tool-reference.mjs            # write docs/tools.md
//   node scripts/generate-tool-reference.mjs --check    # fail if it would change
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));

// Rendered in this order. `intro` is hand-written framing; `tools` is the render order
// within the category.
const CATEGORIES = [
  {
    key: 'discover',
    title: 'Discover',
    intro: '',
    tools: [
      'get_status', 'get_project_info', 'get_tempo', 'list_channels', 'get_channel',
      'list_parameters', 'list_available_patterns', 'list_available_effects',
      'list_available_modulators', 'list_modulations', 'get_parameter', 'get_palette',
      'list_snapshots', 'get_frame', 'get_component_doc',
    ],
  },
  {
    key: 'camera',
    title: 'Camera: where the model is seen from',
    intro: `A walk-in installation is judged from inside it, and \`get_frame\`'s \`front\`/\`top\`/\`side\`
planes are all outside elevations. The camera puts the eye wherever a visitor would stand.

It is an orbit rig, LX's own: \`target\` is the look-at point, \`radius\` the distance out to
the eye, \`theta\` the azimuth in degrees (0 looks from -Z toward +Z, the same viewpoint as
\`get_frame\`'s \`front\` plane) and \`phi\` the elevation (positive looks down, negative looks
up). Pass \`eye\` instead to place the camera by absolute position. Up is always +Y.

When Chromatik's UI is running this is the 3D preview a person is watching — one camera,
not a private copy — so \`recall_camera\` puts the human and the agent on the same
viewpoint. Headless, the viewpoint is held by the server.

Framing a good interior angle takes trial and error, and an unnamed one is unrepeatable.
Named angles are saved in the project file, which makes successive renders comparable
(same angle, so the difference is the pattern's) and gives a PR shared vocabulary.

\`\`\`
set_camera {eye: {x: 0, y: 0, z: 0}, target: {x: 0, y: 400, z: 0}, fovDegrees: 110}
save_camera {name: "stage-looking-up"}
recall_camera {name: "stage-looking-up"}
animate_camera {to: "stage-looking-up", durationMs: 4000}
\`\`\`

Camera moves are not \`LXCommand\`-backed, so none of these appear in Chromatik's undo
history.`,
    tools: [
      'get_camera', 'set_camera', 'animate_camera', 'save_camera', 'list_cameras', 'recall_camera',
      'remove_camera',
    ],
  },
  {
    key: 'point-style',
    title: 'Live preview point style',
    intro: `These settings belong to Chromatik's live GLX preview and have no canonical
\`/lx/...\` path. They persist with that preview's project state, but are unavailable in a
headless LX runtime. \`get_frame\` uses a separate filled-disc raster and does not reproduce
sparkle, LED textures, or the other preview-only controls.`,
    tools: ['get_point_style', 'set_point_style'],
  },
  {
    key: 'project',
    title: 'Save the project & model',
    intro: `Everything built over this API lives only in the running engine until \`save_project\`
writes a \`.lxp\` file — restart Chromatik without saving and it's gone. Neither tool is
\`LXCommand\`-backed (writing a file is an action, not undoable engine state), so neither
appears in Chromatik's undo history. \`save_project\` writes through to a linked external
model file whenever \`get_project_info\`'s \`model.syncModelFile\` is on — \`save_model\` to a
new path first if that file is shared with other projects on the rig and shouldn't be
touched.`,
    tools: ['save_project', 'save_model'],
  },
  {
    key: 'parameters',
    title: 'Read & set parameters',
    intro: `\`set_parameter {path, value}\` dispatches on the parameter's runtime type (number /
integer / boolean / string) and rejects what can't be set sanely: aggregate parameters
(set a color's \`.../hue\`, \`.../saturation\`, \`.../brightness\` components instead),
computed read-only parameters, out-of-range enum indices (LX would silently wrap), and
momentary triggers (see \`fire_trigger\`). Discrete/selector parameters also accept an
**option name string** — \`{"value": "Cylinder"}\` maps a device to a view by label, no
index lookup needed. The response echoes the **base** value, so set-then-verify works
even while modulation rides on top.

\`class\` arguments everywhere (\`add_pattern\`, \`add_effect\`, \`add_modulator\`,
\`get_component_doc\`) accept either the full class name or the short \`name\` the
\`list_available_*\` tools return; an ambiguous short name errors listing the candidates.`,
    tools: ['set_parameter'],
  },
  {
    key: 'history',
    title: 'Undo and redo',
    intro: `Chromatik and every connected MCP client share one linear command history. Each call
moves exactly one command between the undo and redo stacks; it cannot recover an older
change without also undoing every newer command first.`,
    tools: ['undo', 'redo'],
  },
  {
    key: 'structure',
    title: 'Build structure: channels, patterns, effect chains',
    intro: `Effect chains run serially in list order, on channels, the master bus, or an individual
pattern. Structural paths are 1-based and reindex on remove/insert — re-list rather than
reusing cached paths.`,
    tools: [
      'add_channel', 'remove_channel', 'move_channel', 'group_channels', 'ungroup_channel',
      'ungroup_channels', 'copy_channel', 'add_pattern', 'remove_pattern', 'move_pattern',
      'copy_pattern', 'activate_pattern', 'add_effect', 'remove_effect', 'move_effect', 'copy_effect',
    ],
  },
  {
    key: 'modulation',
    title: 'Map macro knobs (and any modulation)',
    intro: '',
    tools: [
      'add_modulator', 'remove_modulator', 'move_modulator', 'wire_modulator',
      'wire_trigger', 'remove_modulation', 'fire_trigger',
      'list_stages', 'add_stage', 'remove_stage', 'set_stage',
    ],
  },
  {
    key: 'palette',
    title: 'Palette & snapshots',
    intro: '',
    tools: [
      'save_swatch', 'set_swatch', 'remove_swatch', 'move_swatch', 'add_color',
      'remove_color', 'add_snapshot', 'recall_snapshot', 'update_snapshot',
      'remove_snapshot',
    ],
  },
  {
    key: 'views',
    title: 'Model views: spatial composition',
    intro: `Views are named subsets of the model ("Cube Interior", "Faces Exterior"), defined by a
tag selector; every channel, pattern, and effect has a \`view\` parameter that clips its
rendering to one. This is how one project paints different geometry with different
content.

Selectors are a small CSS-like language over model tags — space for descendant, \`,\`
union, \`&\` intersect, \`;\` separate groups, \`*\` group-by, \`tag[n-m]\` index ranges (full
grammar in the \`get_views\` tool description).

\`\`\`
add_view {label: "Front+Back", selector: "cubeFrontExterior ; cubeBackExterior", orientation: "group"}
set_parameter {path: /lx/mixer/channel/1/pattern/1/view, value: "Front+Back"}
\`\`\``,
    tools: ['get_views', 'add_view', 'remove_view'],
  },
  {
    key: 'fixtures',
    title: 'Model & fixtures',
    intro: `\`describe_model\` walks the model tree those view selectors match against (depth-limited;
re-call with a child's path or a higher depth to keep descending) — its
\`pointIndexRange\` fields index the same global color buffer \`get_frame\` reports.
\`list_fixtures\`/\`get_fixture\` report the physical wiring layer beneath that model tree —
output protocol (universe/channel/host) and geometry transform, one entry per fixture.
\`set_fixture_params\` is the batched, undo-grouped way to set several fixture parameters at
once, and the only way to reach a JSON fixture's \`.lxf\`-declared \`jsonParameters\` (e.g.
controller IP strings), which have no canonical path. \`set_fixture_tags\` sets a fixture's
model tags (the \`get_views\` selector vocabulary) with pre-write validation. \`reload_fixtures\`
picks up \`.lxf\` edits made on disk — nothing does so automatically.`,
    tools: [
      'describe_model', 'get_fixture_format', 'list_available_fixtures', 'list_fixtures',
      'get_fixture', 'get_output_map', 'add_fixture', 'remove_fixture', 'move_fixture',
      'duplicate_fixture', 'set_fixture_params', 'set_fixture_tags', 'reload_fixtures',
    ],
  },
  {
    key: 'midi',
    title: 'MIDI',
    intro: `Read-side only for now: devices (inputs/outputs), the parameter mappings incoming
MIDI drives, and connected control surfaces. Ports/mappings/surfaces carry no
canonical path, so each is addressed by its 0-based list index — re-list before
reusing one, since indices shift when the underlying list changes.`,
    tools: [
      'list_midi_devices', 'list_midi_mappings', 'list_midi_surfaces',
      'list_midi_templates', 'add_midi_template', 'add_midi_mapping',
      'remove_midi_mapping', 'set_midi_input', 'set_midi_surface_enabled',
    ],
  },
  {
    key: 'composition',
    title: 'Composition: the arrange timeline',
    intro: `The arrange-window composition at \`/lx/timeline/composition\` — transport, markers,
locators, lane lifecycle, audio/text lanes, and the record-arm. (Automation events
within a lane have their own section below.) Timeline
positions travel as **cursor objects**: reads always emit the full
\`{millis, beatCount, beatBasis, formatted}\`; writes take exactly one of
\`{millis}\` | \`{beatCount[, beatBasis]}\` | \`{bars[, beats, sixteenths]}\` (1-indexed) |
\`{at: <origin>[, offsetBeats | offsetMillis]}\`. The clip's \`timeBase\` decides which
fields are authoritative — under \`TEMPO\`, millis are derived from the clip's fixed
\`referenceBpm\`, not the live tempo. Lane paths (\`.../lane/<n>\`) and event indices are
positional and shift under edits: re-list rather than reuse them. Clip behavior
parameters (\`timeBase\`, \`loop\`, \`referenceBpm\`, \`/lx/timeline/sync\`) are ordinary
registered parameters for \`set_parameter\`; marker positions are not.`,
    tools: [
      'get_composition', 'get_clip', 'list_clip_lanes', 'add_clip', 'remove_clip',
      'capture_clip', 'launch_clip', 'stop_clip', 'launch_scene', 'set_clip_marker', 'list_locators', 'add_locator', 'remove_locator', 'move_locator',
      'go_locator', 'add_clip_lane', 'remove_clip_lane', 'move_clip_lane',
      'set_clip_lane_visible', 'add_audio_lane', 'add_notes_lane', 'set_composition_arm',
    ],
  },
  {
    key: 'composition-events',
    title: 'Composition events: automation points & ranges',
    intro: `Automation events have no canonical path — an event's address is the pair
\`{lanePath, index}\`, where \`index\` is its absolute 0-based position in the lane's
event list, and it shifts on every insert or remove. Never carry an index across a
mutation: re-read the lane with \`get_clip_lane\`, or pass \`atCursor\` on event-editing
tools to fail safely if the event moved. Point moves silently clamp between the
neighboring events and the clip bounds (a point can never cross a neighbor — remove
and re-insert to leapfrog), so always trust the echoed \`cursor\`/\`value\` in a payload
over what you sent. Range tools are lane-scoped — LX has no clip-wide range command —
and an empty range is a benign success with \`removedCount: 0\` that puts nothing on
the undo stack.`,
    tools: [
      'get_clip_lane', 'add_automation_point', 'set_automation_point',
      'remove_automation_point', 'remove_clip_range', 'collapse_clip_range',
      'add_clip_note', 'set_clip_note',
    ],
  },
  {
    key: 'batch',
    title: 'Batch',
    intro: `Run several mutation-tool calls in one round-trip, all inside a single engine frame.
Undo is **not** batched: each operation still produces its own undo entry, and per the
tool's own description, one failing operation in a batch can wipe undo history for
earlier operations in that same batch even though they still report success.`,
    tools: ['apply_operations'],
  },
];

const PREAMBLE = `# Tool reference

Every MCP tool the server exposes, generated from the same JSON-Schema \`inputSchema\` each
tool advertises over the wire — never hand-transcribed, so it can't drift from what a
client actually sees. A connected client gets the authoritative version from \`tools/list\`;
[tools.json](tools.json) is the same data as machine-readable JSON.

Everything is addressed by canonical LX path (e.g. \`/lx/mixer/channel/1/fader\`), as
returned by the discovery tools. Mutations are undoable in Chromatik with Cmd-Z unless
noted.

House rules for actually driving a live instance well — discovery etiquette, restart
handling, verifying your own work — are in
[the driving skill](../agent-plugin/skills/driving-chromatik/SKILL.md).`;

const OSC_NOTE = `## OSC

Parameter payloads carry the address an OSC controller must send to. For most
parameters it equals the canonical path, but **modulator knobs answer at label-based
addresses** (\`/lx/modulation/Knobs/macro1\`, not \`.../modulator/1/macro1\`) — renaming a
modulator moves its OSC address. Ports are in \`get_project_info\` (defaults: 3030
receive / 4040 transmit).`;

function schemaTypeLabel(schema) {
  if (!schema) return '—';
  const base = Array.isArray(schema.type) ? schema.type.join(' \\| ') : (schema.type ?? 'any');
  if (schema.type === 'array' && schema.items?.type) {
    return `array<${schema.items.type}>`;
  }
  return base;
}

function schemaConstraints(schema) {
  if (!schema) return '—';
  const bits = [];
  if (schema.enum) bits.push('one of: ' + schema.enum.map((v) => `\`${v}\``).join(', '));
  if (schema.minimum !== undefined || schema.maximum !== undefined) {
    bits.push(`${schema.minimum ?? '-∞'}–${schema.maximum ?? '∞'}`);
  }
  return bits.length ? bits.join('; ') : '—';
}

function escapeCell(text) {
  return String(text ?? '').replaceAll('|', '\\|').replaceAll('\n', ' ');
}

// One-liner for the index table. Tool descriptions front-load their summary, so a plain
// length cut on a word boundary reads better than sentence detection would: these are
// full of colons ("The engine tempo: ...") and abbreviations ("(e.g. /lx/...)") that
// naive first-sentence logic truncates to nothing useful.
const SUMMARY_CHARS = 150;
function summarize(description) {
  const text = String(description ?? '').replaceAll(/\s+/g, ' ').trim();
  if (text.length <= SUMMARY_CHARS) return escapeCell(text);
  const cut = text.slice(0, SUMMARY_CHARS);
  const lastSpace = cut.lastIndexOf(' ');
  return escapeCell((lastSpace > 0 ? cut.slice(0, lastSpace) : cut).replace(/[,;:—-]$/, '') + '…');
}

// GitHub's heading slugger: lowercase, strip punctuation (the backticks around the tool
// name), spaces to hyphens — underscores are kept, so `### \`get_status\`` is #get_status.
const anchor = (name) => name.toLowerCase().replaceAll(/[^a-z0-9_-]/g, '');

function renderIndex(toolsByName) {
  const lines = ['## Index', ''];
  for (const category of CATEGORIES) {
    lines.push(`**${category.title}**`, '');
    lines.push('| tool | | what it does |');
    lines.push('|---|---|---|');
    for (const name of category.tools) {
      const tool = toolsByName[name];
      const badge = tool.readOnly ? 'read' : 'write';
      lines.push(`| [\`${name}\`](#${anchor(name)}) | ${badge} | ${summarize(tool.description)} |`);
    }
    lines.push('');
  }
  return lines.join('\n');
}

function renderTool(tool) {
  const props = tool.inputSchema?.properties ?? {};
  const required = new Set(tool.inputSchema?.required ?? []);
  const paramNames = Object.keys(props);

  const lines = [];
  lines.push(`### \`${tool.name}\``);
  lines.push('');
  lines.push(tool.readOnly ? '_read-only_' : '_mutating_');
  lines.push('');
  lines.push(escapeCell(tool.description));
  lines.push('');

  if (paramNames.length === 0) {
    lines.push('No parameters.');
  } else {
    lines.push('| param | type | required | constraints | description |');
    lines.push('|---|---|---|---|---|');
    for (const name of paramNames) {
      const schema = props[name];
      lines.push(
        `| \`${name}\` | ${schemaTypeLabel(schema)} | ${required.has(name) ? 'yes' : 'no'} | ` +
          `${schemaConstraints(schema)} | ${escapeCell(schema.description)} |`,
      );
    }
  }
  lines.push('');
  return lines.join('\n');
}

const catalog = JSON.parse(await readFile(here('../docs/tools.json'), 'utf8'));
const toolsByName = Object.fromEntries(catalog.map((t) => [t.name, t]));

// Drift guard: every catalog tool must be mapped to exactly one category.
const mappedNames = CATEGORIES.flatMap((c) => c.tools);
const mappedCounts = new Map();
for (const name of mappedNames) {
  mappedCounts.set(name, (mappedCounts.get(name) ?? 0) + 1);
}
const catalogNames = new Set(catalog.map((t) => t.name));
const unmapped = catalog.map((t) => t.name).filter((name) => !mappedCounts.has(name));
const duplicateMapped = [...mappedCounts.entries()].filter(([, count]) => count > 1).map(([name]) => name);
const unknownMapped = mappedNames.filter((name) => !catalogNames.has(name));

if (unmapped.length || duplicateMapped.length || unknownMapped.length) {
  const problems = [];
  if (unmapped.length) problems.push(`unmapped tools (add to a category in generate-tool-reference.mjs): ${unmapped.join(', ')}`);
  if (duplicateMapped.length) problems.push(`tools mapped to more than one category: ${duplicateMapped.join(', ')}`);
  if (unknownMapped.length) problems.push(`mapped names that no longer exist in tools.json: ${unknownMapped.join(', ')}`);
  console.error('generate-tool-reference.mjs: category mapping is out of sync with tools.json:\n  ' + problems.join('\n  '));
  process.exit(1);
}

const sections = [PREAMBLE, renderIndex(toolsByName)];
for (const category of CATEGORIES) {
  const parts = [`## ${category.title}`];
  if (category.intro) parts.push(category.intro);
  parts.push(category.tools.map((name) => renderTool(toolsByName[name])).join('\n').trimEnd());
  sections.push(parts.join('\n\n'));
}
sections.push(OSC_NOTE);

const doc = sections.join('\n\n') + '\n';
const docPath = here('../docs/tools.md');

if (process.argv.includes('--check')) {
  const current = await readFile(docPath, 'utf8').catch(() => null);
  if (current !== doc) {
    console.error(
      'generate-tool-reference.mjs: docs/tools.md is stale relative to docs/tools.json — ' +
        'run `node scripts/generate-tool-reference.mjs`.',
    );
    process.exit(1);
  }
  console.log('docs/tools.md is up to date with docs/tools.json');
  process.exit(0);
}

await writeFile(docPath, doc);
console.log(`wrote ${catalog.length} tools across ${CATEGORIES.length} categories into docs/tools.md`);
